3	import (
4		"bytes"
5		"os/exec"
6		"strings"
7		"testing"
8	)
9	
10	// Command-line regression coverage for how "aggregate" selects its input mode
11	// from --partitions. Omitting the flag and passing an explicit count are
12	// different modes and must not be conflated by the parsed value alone: the
13	// default 0 means legacy single-watermark mode, while any explicitly given
14	// positive count (including 1) means partitioned mode with per-record
15	// partition validation. These tests drive the real main() in a child process
16	// (see main_test.go for the harness) and assert on the process exit code,
17	// standard output and standard error separately, so an argument error (exit
18	// 2, before any input is read) stays distinguishable from a record error
19	// (exit 1, after processing has started).
20	
21	// runAggregateCLI runs the aggregate command in a child process with the
22	// given flags and standard input, returning the exit code and what the
23	// process wrote to standard output and standard error.
24	func runAggregateCLI(t *testing.T, input string, args ...string) (int, string, string) {
25		t.Helper()
26		cmd := aggregateCommand(t, input, args...)
27		var stdout, stderr bytes.Buffer
28		cmd.Stdout = &stdout
29		cmd.Stderr = &stderr
30		runErr := cmd.Run()
31		code := 0
32		if runErr != nil {
33			exitErr, ok := runErr.(*exec.ExitError)
34			if !ok {
35				t.Fatalf("aggregate did not run: %v", runErr)
36			}
37			code = exitErr.ExitCode()
38		}
39		return code, stdout.String(), stderr.String()
40	}
41	
42	// Without --partitions the command keeps the single-watermark behavior:
43	// plain event and watermark records carry no partition field, and a record
44	// that still brings one has it ignored as an extra field.
45	func TestAggregateCLIPartitionsOmittedKeepsSingleWatermarkMode(t *testing.T) {
46		input := strings.Join([]string{
47			`{"type":"event","key":"k","time":100,"value":2}`,
48			`{"type":"event","key":"k","time":200,"value":3,"partition":7}`, // extra field ignored
49			`{"type":"watermark","time":1000}`,
50			`{"type":"watermark","time":1500,"partition":9}`, // extra field ignored
51		}, "\n") + "\n"
52	
53		code, stdout, stderr := runAggregateCLI(t, input, "--window-ms", "1000")
54		if code != 0 {
55			t.Fatalf("exit code = %d, want 0; stderr: %s", code, stderr)
56		}
57		if stderr != "" {
58			t.Fatalf("stderr = %q, want empty", stderr)
59		}
60		assertWindowLines(t, stdout, []windowLine{
61			{Key: "k", Start: 0, End: 1000, Count: 2, Sum: 5},
62		})
63	}
64	
65	// An explicit --partitions 1 is partition mode, not "one input, skip the
66	// checks": every event and watermark must carry partition 0, the merged
67	// output keeps the existing key,start,end,count,sum shape with no partition
68	// field, and a normal run exits 0 with empty standard error.
69	func TestAggregateCLIPartitionsOneIsPartitionMode(t *testing.T) {
70		input := strings.Join([]string{
71			`{"type":"event","key":"k","time":100,"value":2,"partition":0}`,
72			`{"type":"event","key":"k","time":200,"value":3,"partition":0}`,
73			`{"type":"watermark","time":1000,"partition":0}`,
74		}, "\n") + "\n"
75	
76		code, stdout, stderr := runAggregateCLI(t, input, "--window-ms", "1000", "--partitions", "1")
77		if code != 0 {
78			t.Fatalf("exit code = %d, want 0; stderr: %s", code, stderr)
79		}
80		if stderr != "" {
81			t.Fatalf("stderr = %q, want empty", stderr)
82		}
83		assertWindowLines(t, stdout, []windowLine{
84			{Key: "k", Start: 0, End: 1000, Count: 2, Sum: 5},
85		})
86	}
87	
88	// The same records that are valid without --partitions become input errors
89	// under --partitions 1: a missing partition field or a value equal to the
90	// count ends the run with exit code 1, the physical line number and the
91	// partition problem on standard error. This is what separates "flag omitted"
92	// from "one partition".
93	func TestAggregateCLIPartitionsOneValidatesEveryRecord(t *testing.T) {
94		cases := []struct {
95			name      string
96			input     string
97			wantLine  string
98			wantInMsg []string
99		}{
100			{
101				"event missing partition",
102				`{"type":"event","key":"k","time":100,"value":2}` + "\n",
103				"line 1", []string{`"partition"`},
104			},
105			{
106				"watermark missing partition",
107				`{"type":"watermark","time":1000}` + "\n",
108				"line 1", []string{`"partition"`},
109			},
110			{
111				"partition equals count",
112				`{"type":"event","key":"k","time":100,"value":2,"partition":1}` + "\n",
113				"line 1", []string{"partition", "[0,1)"},
114			},
115		}
116		for _, tc := range cases {
117			t.Run(tc.name, func(t *testing.T) {
118				code, stdout, stderr := runAggregateCLI(t, tc.input, "--window-ms", "1000", "--partitions", "1")
119				if code != 1 {
120					t.Fatalf("exit code = %d, want 1; stderr: %s", code, stderr)
121				}
122				if stdout != "" {
123					t.Fatalf("stdout = %q, want empty: no window closed before the bad record", stdout)
124				}
125				for _, want := range append([]string{tc.wantLine}, tc.wantInMsg...) {
126					if !strings.Contains(stderr, want) {
127						t.Fatalf("stderr = %q, want it to mention %q", stderr, want)
128					}
129				}
130			})
131		}
132	}
133	
134	// A --partitions count that is zero, negative, not an integer or outside the
135	// signed 64-bit range is an argument error: the command exits 2 with the
136	// reason on standard error only, before any business record is read. Input
137	// that would close a window must not produce results first, and empty input
138	// must not mask the bad argument either.
139	func TestAggregateCLIInvalidPartitionCountExits2BeforeInput(t *testing.T) {
140		badCounts := []struct {
141			name  string
142			value string
143		}{
144			{"zero", "0"},
145			{"negative", "-3"},
146			{"min int64", "-9223372036854775808"},
147			{"not an integer", "two"},
