11	// slidingIdleBatchLines is the shared fixture for the idle-triggered batch
12	// tests: window 1000, slide 600, two partitions. Both partitions feed the
13	// same keys into overlapping windows; partition 0's watermark (1600) is high
14	// enough to close [0,1000) and [600,1600) while partition 1 sits at 100, so
15	// nothing closes until partition 1 declares idle on physical line 12 (blank
16	// lines 1 and 11 count). Key "é" exercises UTF-8 byte ordering ("a" < "b" <
17	// "é" by bytes). The event at 1300 also opens [1200,2200), which stays open
18	// at effective watermark 1600 and must never be emitted.
19	var slidingIdleBatchLines = []string{
20		``, // line 1: blank, counts toward physical line numbers
21		`{"type":"event","key":"a","time":700,"value":5,"partition":0}`,
22		`{"type":"event","key":"b","time":700,"value":2,"partition":0}`,
23		`{"type":"event","key":"é","time":700,"value":1,"partition":0}`,
