46	// prefixFailAtWriter buffers full writes until its failAt-th call, which
47	// accepts only prefix bytes before reporting err.
48	type prefixFailAtWriter struct {
49		calls  int
50		failAt int
51		prefix int
52		err    error
53		got    bytes.Buffer
54	}
55	
56	func (w *prefixFailAtWriter) Write(p []byte) (int, error) {
57		w.calls++
58		if w.calls == w.failAt {
59			k := w.prefix
60			if k > len(p) {
61				k = len(p)
62			}
63			w.got.Write(p[:k])
64			return k, w.err
65		}
66		return w.got.Write(p)
67	}
68	
69	// fullErrWriter accepts every write in full, buffering the bytes, but its
70	// failAt-th call still reports err alongside the complete byte count: the
71	// receiver holds the whole record -- every JSON byte and the trailing
72	// newline -- yet the write is a failure.
73	type fullErrWriter struct {
74		calls  int
75		failAt int
76		err    error
77		got    bytes.Buffer
78	}
79	
80	func (w *fullErrWriter) Write(p []byte) (int, error) {
81		w.calls++
82		w.got.Write(p)
83		if w.calls == w.failAt {
84			return len(p), w.err
85		}
86		return len(p), nil
87	}
88	
89	// shortFailAtWriter buffers full writes until its failAt-th call, which
90	// accepts only accept bytes and reports no error.
91	type shortFailAtWriter struct {
92		calls  int
93		failAt int
94		accept int
95		got    bytes.Buffer
96	}
97	
98	func (w *shortFailAtWriter) Write(p []byte) (int, error) {
99		w.calls++
100		if w.calls == w.failAt {
101			k := w.accept
102			if k > len(p) {
103				k = len(p)
104			}
105			w.got.Write(p[:k])
106			return k, nil
107		}
108		return w.got.Write(p)
109	}
