297				}
298				if !tc.wantError && err != nil {
299					t.Fatalf("unexpected error: %v", err)
300				}
301				if tc.wantError {
302					inputErr, ok := err.(*InputError)
303					if !ok {
304						t.Fatalf("expected *InputError, got %T: %v", err, err)
305					}
306					if inputErr.Line != len(tc.lines)+1 {
307						t.Errorf("line = %d, want %d", inputErr.Line, len(tc.lines)+1)
308					}
309					if !strings.Contains(inputErr.Reason, tc.wantInMsg) {
310						t.Errorf("reason = %q, want substring %q", inputErr.Reason, tc.wantInMsg)
311					}
312				}
313			})
314		}
